import {useEffect} from "react"
import {Provider} from "react-redux"
import {Routes, Route, HashRouter} from "react-router-dom"
import {App} from "@capacitor/app"

import {AppLayout} from "../layout/app-layout"
import TOCPage from "../components/toc/page"
import StatsPage from "../components/stats/page"
import Chapter from "../components/gita/chapter"
import SvsnPage from "../components/svsn/page";
import {bookStore} from "../state/book-reducer"

export default function ChapterRouter() {
  useEffect(() => {
    // this is for Android back button, no problem for browser web
    App.addListener('backButton', ({canGoBack}) => {
      if (canGoBack) {
        window.history.back()
      } else {
        App.exitApp()
      }
    })
  }, []);

  return (
    <HashRouter history={history}>
      <Provider store={bookStore}>
        <Routes>
          <Route path="/" element={<AppLayout/>}>
            <Route index element={<TOCPage/>}/>
            <Route path="/stats" element={<StatsPage/>}/>
            {/* 18 Routes below */}
            {
              Array(18).fill(1)
                .map((dummy, i) => i + 1)
                .map(chapNum =>
                  <Route key={chapNum} path={`/${chapNum}`} element={<Chapter chapterNum={chapNum}/>}/>
                )
            }
            <Route path="/vishnu-sahasra-namam" element={<SvsnPage/>}/>
          </Route>
          <Route path="*" element={<AppLayout/>}/>
        </Routes>
      </Provider>
    </HashRouter>
  )
}
