import React from 'react'

import {Sloka} from "./sloka"
import {FloatingMenu} from "../floating-menu/floating-menu";

export function ChapterContent({chapterContent}) {
  if (!chapterContent.slokas) {
    return <></>
  }

  let {
    number,
    name,
    slokas,
    meaning,
    audioTime,
    audioUrl
  } = chapterContent
  let slokaArr = Object.values(slokas)
  let meaningArr = meaning && Object.values(meaning)

  return <>
    <>
      {/*---------------Can be placed anywhere---------------*/}
      <FloatingMenu count={slokaArr.length}/>
    </>
    {/*---------------1. Chapter Title---------------*/}
    <div className={"text-palegoldenrod text-2xl"}>
      {name}
    </div>
    {/*---------------2. Slokam Cards---------------*/}
    <div className="text-left text-xl leading-[1.8]">
      {slokaArr.map((slokam, i) =>
        <Sloka
          key={i + 1}             // react key
          chapNum={number}
          slokaNum={i + 1}

          slokam={slokam}
          meaning={meaningArr && meaningArr[i]}
          audioUrl={audioUrl + "#t=" + audioTime[i + 1]}
        />
      )}
    </div>
    {/*---------------3. Chapter Footer---------------*/}
    <div className="sloka-meaning">
      ఓం తత్స ఇతి శ్రీమద్భగవద్గీతాసు ఉపనిషత్సు బ్రహ్మవిద్యాయాం యోగశాస్త్రే <br/>
      శ్రీకృష్ణార్జున సంవాదే <Footer name={name}/>
    </div>
  </>
}

function Footer({name}) {
  let temp = name.split("–")
  return <>
    {temp[1].replace("గః", "గోనామ")}
    <p>{temp[0]}</p>
  </>
}
